{
  "claim_id": "C043",
  "obligation_id": "C043-B-1",
  "contract": "LIMIT_WARRANT",
  "subject": "A documentation gap does not prove a service failure.",
  "verdict": "SATISFIED",
  "unresolved_conditions": [],
  "rationale": "S005 distinguishes missing documentation from proof of an adverse event. T001 supports applying that distinction here: order records do not establish consumption, and most customers send no support message. Missing history therefore leaves service events unresolved; it does not by itself establish a service failure. This limitation does not rule out failure or deny that other evidence could establish it.",
  "packet_id": "H7-T03-2",
